begin;
create extension if not exists pgtap with schema extensions;
select plan(35);
insert into auth.users(id,email,email_confirmed_at,encrypted_password,invited_at) select ('e2100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'activation-'||n||'@example.test',now(),'synthetic',now() from generate_series(1,6) n;
insert into public.profiles(id,display_name) select id,'QA activación' from auth.users where id::text like 'e2100000-%';
insert into public.agencies(id,name,slug,ars_per_usd) values
 ('e2200000-0000-4000-8000-000000000001','QA activación','qa-activation-a',1000),
 ('e2200000-0000-4000-8000-000000000002','QA activación B','qa-activation-b',1000),
 ('e2200000-0000-4000-8000-000000000003','QA invitación inicial','qa-activation-c',1000);
insert into public.memberships(agency_id,user_id,role,is_active) values
 ('e2200000-0000-4000-8000-000000000001','e2100000-0000-4000-8000-000000000002','agency_superadmin',true),
 ('e2200000-0000-4000-8000-000000000001','e2100000-0000-4000-8000-000000000003','seller',false),
 ('e2200000-0000-4000-8000-000000000001','e2100000-0000-4000-8000-000000000004','admin',true),
 ('e2200000-0000-4000-8000-000000000002','e2100000-0000-4000-8000-000000000002','admin',true);
insert into public.platform_admins(user_id) values ('e2100000-0000-4000-8000-000000000001');
select set_config('test.status_version',(select status_version::text from public.agencies where id='e2200000-0000-4000-8000-000000000001'),true);
select set_config('test.settings_version',(select settings_version::text from public.agencies where id='e2200000-0000-4000-8000-000000000001'),true);
set local role anon;
select throws_ok($$select public.set_agency_active('e2200000-0000-4000-8000-000000000001',false,current_setting('test.status_version')::uuid)$$,'42501',null,'Anonymous denied');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e2100000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.set_agency_active('e2200000-0000-4000-8000-000000000001',false,current_setting('test.status_version')::uuid)$$,'42501',null,'Agency owner is not platform');
select set_config('test.employee_invite',public.begin_agency_user_invitation('e2200000-0000-4000-8000-000000000001','activation-5@example.test','QA','seller')::text,true);
select set_config('request.jwt.claims','{"sub":"e2100000-0000-4000-8000-000000000004","role":"authenticated"}',true);
select throws_ok($$select public.set_agency_active('e2200000-0000-4000-8000-000000000001',false,current_setting('test.status_version')::uuid)$$,'42501',null,'Admin denied');
select set_config('request.jwt.claims','{"sub":"e2100000-0000-4000-8000-000000000003","role":"authenticated","user_metadata":{"role":"platform_admin"}}',true);
select throws_ok($$select public.set_agency_active('e2200000-0000-4000-8000-000000000001',false,current_setting('test.status_version')::uuid)$$,'42501',null,'Forged metadata denied');
reset role;
select public.finish_agency_user_invitation(current_setting('test.employee_invite')::uuid,'e2100000-0000-4000-8000-000000000005',true);
update public.platform_admins set is_active=false where user_id='e2100000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e2100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.set_agency_active('e2200000-0000-4000-8000-000000000001',false,current_setting('test.status_version')::uuid)$$,'42501',null,'Revoked platform denied');
reset role;
update public.platform_admins set is_active=true where user_id='e2100000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.set_agency_active('e2200000-0000-4000-8000-000000000001',null,current_setting('test.status_version')::uuid)$$,'22023',null,'Null state denied');
select throws_ok($$select public.set_agency_active('e2200000-0000-4000-8000-000000000001',true,current_setting('test.status_version')::uuid)$$,'22023',null,'No-op denied');
select set_config('test.owner_invite',public.begin_superadmin_invitation('e2200000-0000-4000-8000-000000000003','activation-6@example.test','QA')::text,true);
reset role;
select public.finish_superadmin_invitation(current_setting('test.owner_invite')::uuid,'e2100000-0000-4000-8000-000000000006',true);
set local role authenticated;
select lives_ok($$select public.set_agency_active('e2200000-0000-4000-8000-000000000001',false,current_setting('test.status_version')::uuid)$$,'Platform deactivates agency');
select is((select is_active from public.agencies where id='e2200000-0000-4000-8000-000000000001'),false,'Inactive state persisted');
select is((select settings_version::text from public.agencies where id='e2200000-0000-4000-8000-000000000001'),current_setting('test.settings_version'),'Configuration version preserved');
select throws_ok($$select public.set_agency_active('e2200000-0000-4000-8000-000000000001',false,current_setting('test.status_version')::uuid)$$,'40001',null,'Stale version denied');
select set_config('request.jwt.claims','{"sub":"e2100000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is(private.current_agency_role('e2200000-0000-4000-8000-000000000001'),null,'Agency access revoked');
select is(private.current_agency_role('e2200000-0000-4000-8000-000000000002'),'admin','Other agency access unchanged');
select throws_ok($$select public.update_agency_settings('e2200000-0000-4000-8000-000000000001',current_setting('test.settings_version')::uuid,'No guardar','1200')$$,'P0002',null,'Inactive agency cannot edit configuration');
select set_config('request.jwt.claims','{"sub":"e2100000-0000-4000-8000-000000000005","role":"authenticated"}',true);
select throws_ok($$select public.accept_agency_user_invitation(current_setting('test.employee_invite')::uuid)$$,'P0002',null,'Inactive agency blocks employee acceptance');
select set_config('request.jwt.claims','{"sub":"e2100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.set_agency_active('e2200000-0000-4000-8000-000000000003',false,(select status_version from public.agencies where id='e2200000-0000-4000-8000-000000000003'))$$,'Platform deactivates owner invitation agency');
select set_config('request.jwt.claims','{"sub":"e2100000-0000-4000-8000-000000000006","role":"authenticated"}',true);
select throws_ok($$select public.accept_superadmin_invitation(current_setting('test.owner_invite')::uuid)$$,'P0002',null,'Inactive agency blocks initial owner acceptance');
reset role;
select is((select count(*) from public.memberships where agency_id='e2200000-0000-4000-8000-000000000001' and is_active),2::bigint,'Active membership flags preserved');
select is((select count(*) from public.memberships where agency_id='e2200000-0000-4000-8000-000000000001' and not is_active),1::bigint,'Inactive membership preserved');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e2100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.set_agency_active('e2200000-0000-4000-8000-000000000001',true,(select status_version from public.agencies where id='e2200000-0000-4000-8000-000000000001'))$$,'Platform reactivates agency');
select throws_ok($$select public.set_agency_active('e2200000-0000-4000-8000-000000000001',false,current_setting('test.status_version')::uuid)$$,'40001',null,'Original version remains stale after restoration');
select set_config('request.jwt.claims','{"sub":"e2100000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is(private.current_agency_role('e2200000-0000-4000-8000-000000000001'),'agency_superadmin','Active membership access restored');
select set_config('request.jwt.claims','{"sub":"e2100000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select is(private.current_agency_role('e2200000-0000-4000-8000-000000000001'),null,'Inactive member stays denied after reactivation');
select set_config('request.jwt.claims','{"sub":"e2100000-0000-4000-8000-000000000005","role":"authenticated"}',true);
select lives_ok($$select public.accept_agency_user_invitation(current_setting('test.employee_invite')::uuid)$$,'Still-valid employee invitation resumes after reactivation');
reset role;
select is((select count(*) from public.audit_events where agency_id='e2200000-0000-4000-8000-000000000001' and action in ('agency.activated','agency.deactivated') and actor_id='e2100000-0000-4000-8000-000000000001' and previous_is_active<>new_is_active),2::bigint,'Only actual status transitions audited with actor and states');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e2100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.set_agency_active('e2200000-0000-4000-8000-000000000003',true,(select status_version from public.agencies where id='e2200000-0000-4000-8000-000000000003'))$$,'Platform reactivates initial-owner agency');
select throws_ok($$select public.set_agency_active('e2200000-0000-4000-8000-000000000099',false,current_setting('test.status_version')::uuid)$$,'P0002',null,'Missing agency denied');
select throws_ok($$select public.set_agency_active('e2200000-0000-4000-8000-000000000001',false,null)$$,'22023',null,'Missing version denied');
select set_config('request.jwt.claims','{"sub":"e2100000-0000-4000-8000-000000000006","role":"authenticated"}',true);
select lives_ok($$select public.accept_superadmin_invitation(current_setting('test.owner_invite')::uuid)$$,'Still-valid owner invitation resumes after reactivation');
reset role;
select throws_ok($$insert into public.audit_events(agency_id,actor_id,action,previous_is_active,new_is_active) values('e2200000-0000-4000-8000-000000000001','e2100000-0000-4000-8000-000000000001','agency.activated',true,false)$$,'23514',null,'Audit action must match state pair');
create function pg_temp.reject_activation_audit() returns trigger language plpgsql as $$ begin if new.action='agency.deactivated' then raise exception 'Synthetic audit failure' using errcode='22000'; end if; return new; end; $$;
create trigger reject_activation_audit before insert on public.audit_events for each row execute function pg_temp.reject_activation_audit();
select set_config('test.restored_version',(select status_version::text from public.agencies where id='e2200000-0000-4000-8000-000000000001'),true);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e2100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.set_agency_active('e2200000-0000-4000-8000-000000000001',false,current_setting('test.restored_version')::uuid)$$,'22000',null,'Audit failure rejects transition');
select is((select is_active from public.agencies where id='e2200000-0000-4000-8000-000000000001'),true,'State rolled back');
select is((select status_version::text from public.agencies where id='e2200000-0000-4000-8000-000000000001'),current_setting('test.restored_version'),'Version rolled back');
select throws_ok($$update public.agencies set is_active=false$$,'42501',null,'Direct table mutation denied');
select throws_ok($$insert into public.audit_events(agency_id,actor_id,action,previous_is_active,new_is_active) values('e2200000-0000-4000-8000-000000000001',auth.uid(),'agency.activated',false,true)$$,'42501',null,'Direct audit forgery denied');
select * from finish(); rollback;
